//! Build script for `player-rs`.
//!
//! At build time this script obtains the prebuilt **static** libmpv (and the libraries it depends on) for the current
//! target and links it statically into the crate.
//!
//! The raw FFI bindings are **not** generated here: they are pre-generated by the `xtask` crate and committed to
//! `src/sys/bindings.rs`, so building this crate needs neither `bindgen` nor `libclang`.
//!
//! Binaries come from: https://github.com/vegidio/binaries-mpv/releases
//!
//! The binaries are normally downloaded from the pinned release and cached under the build's `OUT_DIR`. To build
//! offline (or against a custom build of mpv), set the `PLAYER_BINARIES_DIR` environment variable to a directory that
//! contains `include/` and `lib/` subdirectories laid out like the release archives.
//!
//! ## Linking
//!
//! An archive holds far more static libraries than libmpv needs (build leftovers such as abseil or a second TLS stack),
//! so the link line is not "everything in `lib/`". It is resolved from the archive's relocatable `lib/pkgconfig/*.pc`
//! files, starting at `mpv.pc`, by the small reader in `build/pkgconfig.rs`; no `pkg-config` binary is needed. Modules
//! the archive only names (the Linux display and audio stacks) are read from the host's pkg-config directories and
//! linked dynamically.
//!
//! The libraries are emitted as `cargo:rustc-link-lib`, not `cargo:rustc-link-arg`: Cargo applies link args only to
//! this package's own binaries, tests and examples, so a crate that depends on `player-rs` would link without libmpv.
//! The static libraries are bundled into this crate's rlib.

#[path = "build/archive.rs"]
mod archive;
#[path = "build/pkgconfig.rs"]
mod pkgconfig;

use std::env;
use std::fs;
use std::io;
use std::path::{Path, PathBuf};

/// Version of the `binaries-mpv` release to download. The single source of truth is `mpv-version.txt`, read here (and
/// by `xtask`) so the pinned version only has to be bumped in one place. `.trim()` tolerates a trailing newline.
fn mpv_version() -> &'static str {
    include_str!("mpv-version.txt").trim()
}

fn main() {
    println!("cargo:rerun-if-changed=build.rs");
    println!("cargo:rerun-if-changed=mpv-version.txt");
    println!("cargo:rerun-if-changed=build/archive.rs");
    println!("cargo:rerun-if-changed=build/pkgconfig.rs");
    println!("cargo:rerun-if-env-changed=PLAYER_BINARIES_DIR");
    println!("cargo:rerun-if-env-changed=PKG_CONFIG_PATH");
    println!("cargo:rerun-if-env-changed=PKG_CONFIG_LIBDIR");
    println!("cargo:rerun-if-env-changed=MACOSX_DEPLOYMENT_TARGET");

    // docs.rs builds without network access; the committed bindings are enough to document the crate.
    if env::var_os("DOCS_RS").is_some() {
        return;
    }

    check_macos_deployment_target();
    let binaries_dir = locate_binaries();
    emit_link_directives(&binaries_dir.join("lib"));
}

/// Minimum macOS version of the x86_64 archive. libmpv uses Swift, which ships with the OS only from 10.14.4: linked
/// for an older target (Rust's x86_64 default is 10.12), the Swift libraries are referenced through `@rpath` and the
/// binary fails to start. aarch64 targets start at 11.0 and are unaffected.
const MACOS_X64_MIN_VERSION: (u32, u32) = (10, 15);

/// Fails the build on x86_64 macOS unless `MACOSX_DEPLOYMENT_TARGET` is at least [`MACOS_X64_MIN_VERSION`]. A build
/// script cannot raise the deployment target of the final link, so the app has to set it.
fn check_macos_deployment_target() {
    if env::var("CARGO_CFG_TARGET_OS").as_deref() != Ok("macos")
        || env::var("CARGO_CFG_TARGET_ARCH").as_deref() != Ok("x86_64")
    {
        return;
    }

    let target = env::var("MACOSX_DEPLOYMENT_TARGET").unwrap_or_default();
    let mut parts = target.split('.').map(|p| p.parse::<u32>());
    let version = match (parts.next(), parts.next()) {
        (Some(Ok(major)), Some(Ok(minor))) => Some((major, minor)),
        (Some(Ok(major)), None) => Some((major, 0)),
        _ => None,
    };

    let (major, minor) = MACOS_X64_MIN_VERSION;
    if version.is_none_or(|v| v < MACOS_X64_MIN_VERSION) {
        let current = if target.is_empty() { "unset, so Rust's default of 10.12 applies".to_string() } else { target };
        panic!(
            "player-rs: x86_64 macOS builds need MACOSX_DEPLOYMENT_TARGET >= {major}.{minor} (currently {current}); \
             libmpv is built for {major}.{minor} and its Swift runtime would not load on older targets. Set it in your \
             environment or in `.cargo/config.toml`:\n\n[env]\nMACOSX_DEPLOYMENT_TARGET = \"{major}.{minor}\"\n"
        );
    }
}

/// Returns the directory containing the `include/` and `lib/` subdirectories, either from the `PLAYER_BINARIES_DIR`
/// override or by downloading + extracting the pinned release.
fn locate_binaries() -> PathBuf {
    // Resolve the archive name first so an unsupported target fails the same way with or without the override.
    let archive = archive_name();

    if let Some(dir) = env::var_os("PLAYER_BINARIES_DIR") {
        let dir = PathBuf::from(dir);
        for sub in ["include", "lib"] {
            assert!(
                dir.join(sub).is_dir(),
                "player-rs: PLAYER_BINARIES_DIR ({}) is missing the `{sub}/` subdirectory",
                dir.display()
            );
        }
        return dir;
    }

    download_and_extract(&archive)
}

/// Downloads the static archive for the current target into `OUT_DIR` and extracts it.
/// Extraction is skipped if a previous build already populated the cache directory.
fn download_and_extract(archive: &str) -> PathBuf {
    let version = mpv_version();
    let out_dir = PathBuf::from(env::var("OUT_DIR").expect("OUT_DIR not set"));
    let cache_dir = out_dir.join(format!("binaries-mpv-{version}"));

    // Idempotent: a fully extracted cache from a previous build is reused as-is.
    if cache_dir.join("lib").is_dir() && cache_dir.join("include").is_dir() {
        return cache_dir;
    }

    let url = format!("https://github.com/vegidio/binaries-mpv/releases/download/{version}/{archive}");
    eprintln!("player-rs: downloading {url}");

    let bytes = download(&url);
    // Extract beside the cache and rename it into place, so an interrupted extraction can never leave a half-filled
    // cache that the check above would later mistake for a complete one.
    let partial = out_dir.join(format!("binaries-mpv-{version}.partial"));
    let _ = fs::remove_dir_all(&partial);
    extract_zip(&bytes, &partial);
    let _ = fs::remove_dir_all(&cache_dir);
    fs::rename(&partial, &cache_dir)
        .unwrap_or_else(|e| panic!("player-rs: cannot move {} into place: {e}", partial.display()));
    cache_dir
}

/// Maps the Cargo target triple components to the release archive file name, e.g. `static_osx_arm64.zip`.
fn archive_name() -> String {
    let target_os = env::var("CARGO_CFG_TARGET_OS").unwrap();
    let target_arch = env::var("CARGO_CFG_TARGET_ARCH").unwrap();
    let target_env = env::var("CARGO_CFG_TARGET_ENV").unwrap_or_default();

    archive::archive_name(&target_os, &target_arch, &target_env).unwrap_or_else(|e| panic!("player-rs: {e}"))
}

/// Downloads the given URL into memory, following redirects.
fn download(url: &str) -> Vec<u8> {
    let mut reader = ureq::get(url)
        .call()
        .unwrap_or_else(|e| panic!("player-rs: failed to download {url}: {e}"))
        .into_body()
        .into_reader();

    let mut bytes = Vec::new();
    io::copy(&mut reader, &mut bytes)
        .unwrap_or_else(|e| panic!("player-rs: failed to read response body from {url}: {e}"));
    bytes
}

/// Extracts a zip archive (held entirely in memory) into `dest`.
fn extract_zip(bytes: &[u8], dest: &Path) {
    let reader = io::Cursor::new(bytes);
    let mut zip = zip::ZipArchive::new(reader).expect("player-rs: invalid zip archive");

    for i in 0..zip.len() {
        let mut entry = zip.by_index(i).expect("player-rs: corrupt zip entry");
        let Some(rel_path) = entry.enclosed_name() else {
            continue; // skip unsafe / absolute paths
        };
        let out_path = dest.join(rel_path);

        if entry.is_dir() {
            fs::create_dir_all(&out_path).unwrap();
            continue;
        }

        if let Some(parent) = out_path.parent() {
            fs::create_dir_all(parent).unwrap();
        }
        let mut out_file = fs::File::create(&out_path)
            .unwrap_or_else(|e| panic!("player-rs: cannot create {}: {e}", out_path.display()));
        io::copy(&mut entry, &mut out_file).expect("player-rs: failed to extract file");
    }
}

/// Resolves the link line from the archive's `mpv.pc` and tells Cargo/rustc where the libraries live and which to link.
fn emit_link_directives(lib_dir: &Path) {
    let target_os = env::var("CARGO_CFG_TARGET_OS").unwrap();
    let msvc = env::var("CARGO_CFG_TARGET_ENV").as_deref() == Ok("msvc");

    let plan = pkgconfig::Resolver::new(&target_os, msvc, lib_dir, system_pkgconfig_dirs(&target_os))
        .and_then(|resolver| resolver.resolve("mpv"))
        .unwrap_or_else(|e| panic!("player-rs: cannot resolve the libmpv link line: {e}"));

    for dir in &plan.search_paths {
        println!("cargo:rustc-link-search=native={}", dir.display());
    }

    let mut static_libs = Vec::new();
    for lib in &plan.libs {
        match lib {
            pkgconfig::Lib::Static(name) => {
                println!("cargo:rustc-link-lib=static={name}");
                static_libs.push(name);
            }
            pkgconfig::Lib::Dylib(name) => println!("cargo:rustc-link-lib=dylib={name}"),
            pkgconfig::Lib::Framework(name) => println!("cargo:rustc-link-lib=framework={name}"),
        }
    }

    // This package's own test binaries link the archives above directly (not via the bundled rlib). The single-pass
    // GNU `bfd` linker (the default on aarch64 Linux) can then miss back-references between them. Re-listing the set
    // in a link group (appended after the `-l` flags) resolves them. Link args only apply to this package's targets;
    // dependents use the rlib.
    if target_os == "linux" {
        println!("cargo:rustc-link-arg=-Wl,--start-group");
        for name in &static_libs {
            println!("cargo:rustc-link-arg=-l{name}");
        }
        println!("cargo:rustc-link-arg=-Wl,--end-group");
    }
}

/// The host pkg-config directories searched for modules the archive does not ship, in pkg-config's order:
/// `PKG_CONFIG_PATH`, then `PKG_CONFIG_LIBDIR` or, on Linux, the standard system directories.
fn system_pkgconfig_dirs(target_os: &str) -> Vec<PathBuf> {
    let split = |var: &str| env::var_os(var).map(|v| env::split_paths(&v).collect::<Vec<_>>());

    let mut dirs = split("PKG_CONFIG_PATH").unwrap_or_default();
    if let Some(libdir) = split("PKG_CONFIG_LIBDIR") {
        dirs.extend(libdir);
    } else if target_os == "linux" {
        let multiarch = match env::var("CARGO_CFG_TARGET_ARCH").as_deref() {
            Ok("x86_64") => "x86_64-linux-gnu",
            _ => "aarch64-linux-gnu",
        };
        for dir in [
            format!("/usr/local/lib/{multiarch}/pkgconfig"),
            "/usr/local/lib/pkgconfig".to_string(),
            "/usr/local/share/pkgconfig".to_string(),
            format!("/usr/lib/{multiarch}/pkgconfig"),
            "/usr/lib/pkgconfig".to_string(),
            "/usr/share/pkgconfig".to_string(),
        ] {
            dirs.push(PathBuf::from(dir));
        }
    }
    dirs
}
